package com.creedpdf.orbitalrailgun.registry;

import com.creedpdf.orbitalrailgun.RailgunMod;
import net.fabricmc.fabric.api.particle.v1.FabricParticleTypes;
import net.minecraft.particle.DefaultParticleType;
import net.minecraft.registry.Registries;
import net.minecraft.registry.Registry;

/**
 * Custom particle types. Their sprites are in assets/orbital_railgun/textures/particle/
 * (generated by tools/textures/build_textures.py) and their behaviour is defined client-side in
 * {@code RailgunParticle}. All are "always show" so the huge effects render at long range and on
 * reduced particle settings.
 */
public final class ModParticles {
    private ModParticles() {}

    public static final DefaultParticleType PLASMA_SPARK = register("plasma_spark");
    public static final DefaultParticleType ENERGY_MOTE = register("energy_mote");
    public static final DefaultParticleType PLASMA_SMOKE = register("plasma_smoke");
    public static final DefaultParticleType REENTRY_FIRE = register("reentry_fire");
    public static final DefaultParticleType EMBER = register("ember");
    public static final DefaultParticleType DEBRIS = register("debris");
    public static final DefaultParticleType FLASH = register("flash");
    public static final DefaultParticleType SHOCK_DUST = register("shock_dust");
    // loadout / orbital storage
    public static final DefaultParticleType SPALL = register("spall");
    public static final DefaultParticleType THERMITE_FLAME = register("thermite_flame");
    public static final DefaultParticleType FROST = register("frost");
    public static final DefaultParticleType ION_ARC = register("ion_arc");
    public static final DefaultParticleType BOMBLET = register("bomblet");
    public static final DefaultParticleType SINGULARITY_MOTE = register("singularity_mote");
    public static final DefaultParticleType FALLOUT = register("fallout");
    public static final DefaultParticleType LENS_GLINT = register("lens_glint");
    public static final DefaultParticleType COOLANT_VAPOR = register("coolant_vapor");
    public static final DefaultParticleType OVERCLOCK_SPARK = register("overclock_spark");
    public static final DefaultParticleType SHIELD_SPARK = register("shield_spark");
    public static final DefaultParticleType SENTRY_BOLT = register("sentry_bolt");
    public static final DefaultParticleType THRUSTER_FLAME = register("thruster_flame");
    public static final DefaultParticleType SEISMIC_CRACK = register("seismic_crack");
    public static final DefaultParticleType SHELL_CASING = register("shell_casing");
    public static final DefaultParticleType PLASMA_POOL = register("plasma_pool");
    public static final DefaultParticleType TRANSFER_MOTE = register("transfer_mote");

    // ---- v3.1: every option gets its own effects ----
    /** Per ammunition: impact / muzzle flash, smoke and sparks, keyed by Option ordinal. */
    public static final java.util.Map<com.creedpdf.orbitalrailgun.loadout.Loadout.Option, DefaultParticleType> AMMO_FLASH = new java.util.EnumMap<>(com.creedpdf.orbitalrailgun.loadout.Loadout.Option.class);
    public static final java.util.Map<com.creedpdf.orbitalrailgun.loadout.Loadout.Option, DefaultParticleType> AMMO_SMOKE = new java.util.EnumMap<>(com.creedpdf.orbitalrailgun.loadout.Loadout.Option.class);
    public static final java.util.Map<com.creedpdf.orbitalrailgun.loadout.Loadout.Option, DefaultParticleType> AMMO_SPARK = new java.util.EnumMap<>(com.creedpdf.orbitalrailgun.loadout.Loadout.Option.class);
    static {
        for (var o : com.creedpdf.orbitalrailgun.loadout.Loadout.Option.of(com.creedpdf.orbitalrailgun.loadout.Loadout.Category.AMMO)) {
            AMMO_FLASH.put(o, register(o.id + "_flash"));
            AMMO_SMOKE.put(o, register(o.id + "_smoke"));
            AMMO_SPARK.put(o, register(o.id + "_spark"));
        }
    }
    public static final DefaultParticleType PRONG_ARC = register("prong_arc");
    public static final DefaultParticleType SHROUD_FLAME = register("shroud_flame");
    public static final DefaultParticleType SCATTER_FLASH = register("scatter_flash");
    public static final DefaultParticleType GRAVITON_RIPPLE = register("graviton_ripple");
    public static final DefaultParticleType GHOST_WISP = register("ghost_wisp");
    public static final DefaultParticleType CAPACITOR_ARC = register("capacitor_arc");
    public static final DefaultParticleType SENTRY_FLASH = register("sentry_flash");
    public static final DefaultParticleType THRUSTER_SHOCK = register("thruster_shock");
    public static final DefaultParticleType TARGET_PING = register("target_ping");
    public static final DefaultParticleType DRONE_TRAIL = register("drone_trail");
    public static final DefaultParticleType DRONE_JET = register("drone_jet");
    public static final DefaultParticleType DOCK_SPARK = register("dock_spark");
    public static final DefaultParticleType SCAN_MOTE = register("scan_mote");
    public static final DefaultParticleType SCAN_FLARE = register("scan_flare");
    public static final DefaultParticleType RIFT_SPARK = register("rift_spark");
    public static final DefaultParticleType RIFT_DUST = register("rift_dust");
    public static final DefaultParticleType RIFT_FLASH = register("rift_flash");
    public static final DefaultParticleType RIFT_WISP = register("rift_wisp");

    private static DefaultParticleType register(String name) {
        return Registry.register(Registries.PARTICLE_TYPE, RailgunMod.id(name), FabricParticleTypes.simple(true));
    }

    public static void init() {}
}
